    //Node Structure
class Node {
    constructor(x) {
        this.data = x;
        this.left = null;
        this.right = null;
    }
}

function inOrder(node, res) {
    if (node === null)
        return;

    // Traverse the left subtree first
    inOrder(node.left, res);

    // Visit the current node
    res.push(node.data);

    // Traverse the right subtree last
    inOrder(node.right, res);
}

